// HBC+ v1.4 (F1) - Self-test: detect the phase of every battery.
// Started by script.hbc_selftest_run (HA event hbc_selftest_request, action 'start'), after the script has
// put the strategy on 'Self-test' through the Strategy arbiter (requester 'selftest', priority 90).
// Per battery, up to 3 attempts of about 65 s:
//   settle 20 s  all batteries stopped
//   base   10 s  measure the P1 power per phase (baseline)
//   ramp   20 s  only this battery charges at msg.power (default 800 W)
//   meas   15 s  measure the P1 power per phase and the battery power
// The phase whose import rose most is the battery's phase when that rise is at least 60 % of the measured
// battery power and at least twice the second-largest rise. Otherwise: next attempt, after 3 'uncertain'.
// The plan for the 'Self-test' strategy (link in on this tab) is global 'hbc_selftest_plan'
// = {target: 'M2' | null, power, expires}. It expires after 2 minutes, so a stopped Node-RED or a
// crashed test never leaves a battery charging: the strategy then stops every battery.
// Output -> HA event hbc_selftest_phase_result {run_id, status, reason, batteries, changes, finished}.
// Signs: sensor.p1_meter_power_phase_N > 0 = import, sensor.marstek_mN_battery_power > 0 = charging.
const SETTLE_S = 20, BASE_S = 10, RAMP_S = 20, MEAS_S = 15, ATTEMPTS = 3;
const MIN_SHARE = 0.6, MIN_RATIO = 2, MIN_BATT_W = 400, LOST_S = 30, PLAN_MS = 120000;

const ha = global.get('homeassistant');
let states = null;
if (ha && typeof ha === 'object') {
    const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
    const srv = servers.find(s => s.isConnected !== false) || servers[0];
    if (srv) states = srv.states;
}
const raw = (id) => (states && states[id] ? states[id].state : undefined);
const usable = (v) => v !== undefined && v !== null && v !== '' && v !== 'unknown' && v !== 'unavailable';
const num = (id, def) => { const v = raw(id); const n = Number(v); return usable(v) && Number.isFinite(n) ? n : def; };
const str = (id, def) => { const v = raw(id); return usable(v) ? String(v) : def; };

const now = Date.now();
let st = context.get('st') || null;
const setPlan = (target) => global.set('hbc_selftest_plan', { target, power: st.power, expires: now + PLAN_MS });
const go = (step) => { st.step = step; st.t = now; };
const round = (x) => Math.round(x);
const avg = (rows) => rows[0].map((_, k) => rows.reduce((s, r) => s + r[k], 0) / rows.length);

const finish = (status, reason) => {
    global.set('hbc_selftest_plan', null);
    const res = st ? st.results : [];
    let overall = status;
    if (status === 'done') {
        if (res.some(r => !r.certain)) overall = 'uncertain';
        else if (res.some(r => r.change)) overall = 'mismatch';
        else overall = 'ok';
    }
    const payload = {
        run_id: st ? st.run_id : '',
        status: overall,
        reason: reason || '',
        batteries: res,
        changes: res.filter(r => r.change).length,
        finished: new Date(now).toISOString(),
    };
    context.set('st', null);
    node.status({ fill: overall === 'ok' ? 'green' : 'yellow', shape: 'dot', text: `${overall}${reason ? ': ' + reason : ''}`.slice(0, 80) });
    node.send({ payload });
    return null;
};

// ---- requests from HA ----
if (msg.topic === 'hbc_selftest_request') {
    const d = (msg.payload && typeof msg.payload.data === 'object' && msg.payload.data) ? msg.payload.data : (msg.payload || {});
    if (d.action === 'abort') {
        if (!st) return null;
        return finish('aborted', 'stopped from Home Assistant');
    }
    if (d.action !== 'start') return null;
    if (st) { node.warn('Self-test already running, start ignored'); return null; }
    if (!states) {
        st = { run_id: String(d.run_id || ''), results: [] };
        return finish('error', 'no HA states in global context (Expose to global context off?)');
    }
    let power = Number(d.power);
    if (!Number.isFinite(power)) power = 800;
    power = Math.min(1500, Math.max(300, Math.round(power)));
    st = {
        run_id: String(d.run_id || ''), power,
        count: Math.max(0, Math.min(6, num('input_number.house_battery_count', 0))),
        bi: 1, attempt: 1, step: 'settle', t: now, base: [], meas: [], batt: [], results: [], lost: null,
    };
    if (st.count < 1) return finish('error', 'no batteries (input_number.house_battery_count)');
    context.set('st', st);
    setPlan(null);
    node.status({ fill: 'blue', shape: 'dot', text: `M1 attempt 1: settle` });
    return null;
}

// ---- tick (every second) ----
if (!st) return null;
if (!states) return finish('aborted', 'HA states disappeared from global context');

// The 'Self-test' strategy must really be active; another hold or a manual choice stops the test.
if (str('input_select.house_battery_strategy', '') !== 'Self-test') {
    if (!st.lost) st.lost = now;
    if (now - st.lost > LOST_S * 1000) return finish('aborted', 'the strategy is no longer Self-test (manual choice or another hold)');
} else st.lost = null;

const id = `M${st.bi}`;
const el = (now - st.t) / 1000;
const phases = [1, 2, 3].map(i => num(`sensor.p1_meter_power_phase_${i}`, NaN));
const phasesOk = phases.every(Number.isFinite);

const nextBattery = () => {
    st.bi += 1; st.attempt = 1; st.base = []; st.meas = []; st.batt = []; st.socChecked = false;
    if (st.bi > st.count) return finish('done', '');
    go('settle');
    return null;
};

if (st.step === 'settle') {
    if (!st.socChecked) {
        st.socChecked = true;
        // a battery at its charge cutoff cannot charge: skip it
        const soc = num(`sensor.marstek_m${st.bi}_battery_state_of_charge`, NaN);
        const cut = num(`input_number.marstek_m${st.bi}_charging_cutoff_capacity`, 100);
        if (Number.isFinite(soc) && soc >= Math.min(95, cut - 2)) {
            st.results.push({ id, measured: null, current: str(`input_select.marstek_m${st.bi}_phase`, ''), certain: false, change: false,
                battery_w: 0, delta: {}, attempts: 0, note: `battery full (${round(soc)} %), not tested` });
            return nextBattery();
        }
    }
    setPlan(null);
    if (el >= SETTLE_S) go('base');
} else if (st.step === 'base') {
    setPlan(null);
    if (phasesOk) st.base.push(phases);
    if (el >= BASE_S) go('ramp');
} else if (st.step === 'ramp') {
    setPlan(id);
    if (el >= RAMP_S) go('meas');
} else if (st.step === 'meas') {
    setPlan(id);
    if (phasesOk) st.meas.push(phases);
    const bp = num(`sensor.marstek_m${st.bi}_battery_power`, NaN);
    if (Number.isFinite(bp)) st.batt.push(bp);
    if (el >= MEAS_S) {
        setPlan(null);
        const current = str(`input_select.marstek_m${st.bi}_phase`, '');
        let r;
        if (st.base.length < 5 || st.meas.length < 5) {
            r = { certain: false, measured: null, battery_w: 0, delta: {}, note: 'too few P1 phase readings' };
        } else {
            const b = avg(st.base), m = avg(st.meas);
            const d = m.map((x, k) => x - b[k]);
            const bw = st.batt.length ? st.batt.reduce((s, x) => s + x, 0) / st.batt.length : 0;
            const order = [0, 1, 2].sort((a, c) => d[c] - d[a]);
            const best = d[order[0]], second = d[order[1]];
            const delta = { L1: round(d[0]), L2: round(d[1]), L3: round(d[2]) };
            if (bw < MIN_BATT_W) {
                r = { certain: false, measured: null, battery_w: round(bw), delta, note: `battery did not charge (${round(bw)} W)` };
            } else {
                const ok = best >= MIN_SHARE * bw && (second <= 0 || best >= MIN_RATIO * second);
                r = { certain: ok, measured: ok ? `L${order[0] + 1}` : null, battery_w: round(bw), delta,
                      note: ok ? '' : 'house load changed during the measurement' };
            }
        }
        if (!r.certain && st.attempt < ATTEMPTS && !/did not charge/.test(r.note)) {
            st.attempt += 1; st.base = []; st.meas = []; st.batt = [];
            go('settle');
        } else {
            r.change = r.certain && ['L1', 'L2', 'L3'].includes(current) && r.measured !== current;
            st.results.push(Object.assign({ id, current, attempts: st.attempt }, r));
            return nextBattery();
        }
    }
}
node.status({ fill: 'blue', shape: 'dot', text: `${id} attempt ${st.attempt}: ${st.step} ${Math.floor((now - st.t) / 1000)} s` });
return null;

// HBC+ v1.4 (F1) - Self-test, part 1: what only Node-RED can see. Answers the HA event
// hbc_selftest_flow_check (fired by script.hbc_selftest_run) with hbc_selftest_flow_result.
//   global_states  the HA server node exposes its states to global context ('Expose to global context')
//   entities       number of HA states Node-RED sees
//   p1             sensor.p1_meter_power is among them
//   connected      the HA server node is connected
const d = (msg.payload && typeof msg.payload.data === 'object' && msg.payload.data) ? msg.payload.data : (msg.payload || {});
const ha = global.get('homeassistant');
let srv = null;
if (ha && typeof ha === 'object') {
    const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
    srv = servers.find(s => s.isConnected !== false) || servers[0] || null;
}
const states = srv ? srv.states : null;
const entities = states ? Object.keys(states).length : 0;
msg.payload = {
    run_id: String(d.run_id || ''),
    global_states: entities > 0,
    entities,
    p1: !!(states && states['sensor.p1_meter_power']),
    connected: !!(srv && srv.isConnected !== false),
    node_red: RED.version ? RED.version() : '',
};
node.status({ fill: entities ? 'green' : 'red', shape: 'dot', text: entities ? `${entities} HA states` : 'no HA states in global context' });
return msg;

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// HBC+ v1.4 (F1) - 'Self-test' strategy. Only active while script.hbc_selftest_run holds it through the
// Strategy arbiter. Follows the plan of 'Self-test controller' (global 'hbc_selftest_plan'):
// the battery under test charges at the test power, every other battery stops.
// No plan, or a plan older than 2 minutes: every battery stops (same as Full stop).
const plan = global.get('hbc_selftest_plan');
const live = !!(plan && Number.isFinite(plan.expires) && plan.expires > Date.now());
msg.solutions = (msg.batteries || []).map(b => (live && plan.target === b.id)
    ? { id: b.id, mode: 'charge', power: Number(plan.power) || 0 }
    : { id: b.id, mode: 'stop', power: 0 });
node.status(live ? { fill: 'blue', shape: 'dot', text: plan.target ? `${plan.target} charges ${plan.power} W` : 'all stopped (measuring)' }
                 : { fill: 'grey', shape: 'ring', text: 'no test running: all stopped' });
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if (handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}
